list_blogs.code:
import (
	"fmt"
)

resp, err := client.Blogs().ListBlogs(ctx, map[string]any{"visibility": "open", "limit": 20}, nil)
if err != nil {
	log.Fatal(err)
}
body := resp.Map().(map[string]any)
for _, row := range body["blogs"].([]any) {
	blog := row.(map[string]any)
	fmt.Println(blog["id"], blog["title"], blog["date"])
}
pagination := body["pagination"].(map[string]any)
fmt.Println(pagination["total"], pagination["has_next"])

